export const scenarios = Object.freeze(GROUPS.flatMap(group =>
  group.queries.map((entry, index) => {
    const pair = Array.isArray(entry) ? entry : [entry, group.defaultOutput];
    const request = pair[0];
    const expectedOutput = pair[1] || null;
    return Object.freeze({
      id: `SIM${String(GROUPS.slice(0, GROUPS.indexOf(group)).reduce((n, g) => n + g.queries.length, 0) + index + 1).padStart(3, '0')}`,
      department: group.department,
      userRole: group.role,
      userRequest: request,
      context: `จำลองงานประจำของ${group.department} ผู้ใช้ต้องการคำตอบหรือเอกสารที่นำไปทำงานต่อได้ โดยยังไม่มีเลขหนังสือ ชื่อบุคคลจริง หรือข้อมูลส่วนบุคคลจริง`,
      missingInformation: Object.freeze(['ข้อมูลเฉพาะเรื่องที่ผู้ใช้ยังไม่ได้ให้', 'เอกสารต้นฉบับ/หลักฐานเมื่อจำเป็นต่อการยืนยัน']),
      expectedModules: Object.freeze([group.module]),
      expectedOutput,
      expectedBehavior: Object.freeze([
        'ตอบ Answer First',
        'เลือกเครื่องมือเท่าที่จำเป็น',
        'ไม่แต่งข้อเท็จจริงหรือฐานกฎหมาย',
        group.risk === 'high' ? 'ตรวจแหล่งราชการ/ต้นฉบับล่าสุดก่อนฟันธง' : 'ให้ผลลัพธ์พร้อมใช้จากข้อมูลที่มี'
      ]),
      riskLevel: group.risk,
      acceptanceCriteria: COMMON_ACCEPTANCE
    });
  })
));

if (scenarios.length !== 200) throw new Error(`Expected exactly 200 scenarios, got ${scenarios.length}`);

export const scenarioSummary = Object.freeze(
  scenarios.reduce((acc, item) => {
    const moduleId = item.expectedModules[0];
    acc[moduleId] = (acc[moduleId] || 0) + 1;
    return acc;
  }, {})
);
